INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Connected hubs benefit communities as remote working brings locals home', 'connected-hubs-benefit-communities-as-remote-working-brings-locals-home', '<div>
<div></div>
</div>
<div>
<div>
<p>Taking place as part of the government’s national campaign to promoting remote working, the national Showcase Day aimed to encourage more employers, small businesses and start-ups to consider the wide range of remote working options available nationally.</p>
</div>
</div>
<div>
<div>
<p>The event at Creative Spark in Dundalk focused on town regeneration and heard directly from hub users who gave their experience of returning to their local community as a result of the opportunities presented by remote working.</p>
</div>
</div>
<div>
<div>
<p>Minister Humphreys said at the launch: “Today’s initiative is all about showcasing the fantastic remote facilities that are open for business in every single county in Ireland. It’s about promoting the many opportunities and benefits that remote working is providing to tens of thousands of people.</p>
<p>“I believe that by giving people that choice to work from within their own communities, we can revitalise the centres of our towns and villages. We can reduce commuting times, lower transport emissions and, most importantly, improve the quality of life of our people.”</p>
</div>
</div>
<div>
<div>
<p>Connected Hubs is a flagship initiative led by the Department of Rural and Community Development and implemented by the Western Development Commission. The initiative will connect and deepen the remote working infrastructure across rural Ireland.</p>
</div>
</div>
<div>
<div>
<p>The network now has 315 hubs across the country registered on its online platform.</p>
</div>
</div>', 'More than 50 Connected Hubs hosted events nationwide on April 26 to celebrate the national ‘Connected Hubs Showcase Day’. Minister for Rural and Community Development, Heather Humphreys, launched the event at the Creative Spark Downtown Hub in Dundalk, County Louth. The programme included co-working crawls, talks from guest speakers, and coffee mornings all across the country.', 'https://changingireland.ie/wp-content/uploads/2023/04/creative-spark.jpg', '', '[{"slug":"community","title":"Community"}]', '[{"slug":"community-development","title":"community development"},{"slug":"connected-hubs","title":"Connected Hubs"},{"slug":"connected-hubs-showcase-day","title":"Connected Hubs Showcase Day"},{"slug":"county-louth","title":"County Louth"},{"slug":"creative-spark-downtown-hub","title":"Creative Spark Downtown Hub"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"digital-hub","title":"Digital hub"},{"slug":"dundalk","title":"Dundalk"},{"slug":"employment","title":"employment"},{"slug":"ireland","title":"Ireland"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"remote-working","title":"remote working"},{"slug":"rural-development","title":"rural development"},{"slug":"western-development-commission","title":"Western Development Commission"}]', '', 252899, 1, '2023-04-27T11:33:22Z', '2023-04-27T11:33:22Z', '2023-04-27T11:33:22Z')
