INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Increase in over 65s contacting MABS after lifting of Eviction Ban', 'increase-in-over-65s-contacting-mabs-after-lifting-of-eviction-ban', '<p>The organisation says the phased lifting of the ban puts thousands of renters at risk of potential evictions.</p>
<p>MABS revealed that its staff had already been working with a high volume of people seeking support due to the cost of living crisis. They are now seeing people impacted by the lifting of the ban, and those worried about receiving potential eviction notices &#8220;with further financial concern due to energy prices remaining high, despite wholesale prices coming down&#8221;.</p>
<p>The organisation is seeking to reassure people that there are steps in place to support those affected, and that MABS, alongside other support facilities, are there to help those who are worried.</p>
<p>Ursula Collins, regional manager for South Munster MABS said: “We have recorded an increase in people with concerns following the lifting of the eviction ban, many who have immediately been affected, and those who are concerned about when an eviction notice comes.</p>
<p>&#8220;The government has put measures into place to help, such as the purchase with tenant in situ scheme to those eligible, but we do urge tenants facing challenges to contact us. We are here, for free and in confidence, online or in person appointments. For specific housing advice, we will refer you to the right place for support, whether that is Threshold, your local authority, or the Residential Tenancy Board.&#8221;</p>
<p>For more information, see www.mabs.ie, or contact MABS for free, confidential, and independent advice on 0818 07 2000.</p>', 'South Munster Money Advice and Budgeting Service (MABS) has reported an increase in requests for assistance following the lifting of the eviction ban on March 31. MABS, which provides free advice to anyone who wants help in managing their money and taking control of debt, has experienced a significant increase in referrals from over 65s in particular.', 'https://changingireland.ie/wp-content/uploads/2023/04/mabs.png', '', '[{"slug":"equality-rights","title":"Equality & Rights"}]', '[{"slug":"cost-of-living-crisis","title":"cost-of-living crisis"},{"slug":"eviction-ban","title":"Eviction Ban"},{"slug":"housing","title":"housing"},{"slug":"housing-crisis","title":"housing crisis"},{"slug":"ireland","title":"Ireland"},{"slug":"mabs-money-advice-and-budgeting-service","title":"MABS money advice and budgeting service"},{"slug":"residential-tenancy-board","title":"Residential Tenancy Board"},{"slug":"threshold","title":"Threshold"}]', '', 252887, 1, '2023-04-24T10:43:13Z', '2023-04-24T10:43:13Z', '2023-04-24T10:43:13Z')
