INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Maynooth’s youth and community students ready for a friendly grilling', 'maynooths-youth-and-community-students-ready-for-your-questions', '<p>Fresh from a study trip to the western seaboard, they are the key speakers in an online recruitment event for the university&#8217;s two-year Masters in Social Science, Community Work and Youth Work.</p>
<figure aria-describedby="caption-attachment-252874"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2023/04/Deirdre-Massey-is-the-Practice-Development-Coordinator-with-Maynooth-Universitys-Department-of-Applied-Social-Sciences-235x300.jpeg" alt="" width="235" height="300" srcset="https://changingireland.ie/wp-content/uploads/2023/04/Deirdre-Massey-is-the-Practice-Development-Coordinator-with-Maynooth-Universitys-Department-of-Applied-Social-Sciences-235x300.jpeg 235w, https://changingireland.ie/wp-content/uploads/2023/04/Deirdre-Massey-is-the-Practice-Development-Coordinator-with-Maynooth-Universitys-Department-of-Applied-Social-Sciences-802x1024.jpeg 802w, https://changingireland.ie/wp-content/uploads/2023/04/Deirdre-Massey-is-the-Practice-Development-Coordinator-with-Maynooth-Universitys-Department-of-Applied-Social-Sciences-768x981.jpeg 768w, https://changingireland.ie/wp-content/uploads/2023/04/Deirdre-Massey-is-the-Practice-Development-Coordinator-with-Maynooth-Universitys-Department-of-Applied-Social-Sciences-1203x1536.jpeg 1203w, https://changingireland.ie/wp-content/uploads/2023/04/Deirdre-Massey-is-the-Practice-Development-Coordinator-with-Maynooth-Universitys-Department-of-Applied-Social-Sciences-1080x1379.jpeg 1080w, https://changingireland.ie/wp-content/uploads/2023/04/Deirdre-Massey-is-the-Practice-Development-Coordinator-with-Maynooth-Universitys-Department-of-Applied-Social-Sciences.jpeg 1253w" sizes="(max-width: 235px) 100vw, 235px" /><figcaption><em>• Deirdre Massey is the Practice Development Coordinator with Maynooth University&#8217;s Department of Applied Social Sciences.</em></figcaption></figure>
<p>Event organiser Deirdre Massey believes the session is nicely pitched for people wanting social change and wondering whether further study is for them or not:</p>
<p>&#8220;We believe that hearing from past and current students and employers, in a participative session, is a powerful way to communicate the value base of the Department, the pedagogy that students learn through, and the capacity to impact on social change.&#8221;</p>
<p>The event will also give people get a sense of &#8220;the fun and creativity that is part and parcel of the programme&#8221;, she said.</p>
<p>The university is currently the only provider in the country of community work and youth work education at postgraduate level.</p>
<p>&#8220;We really welcome applications from people with diverse backgrounds &#8211; Travellers, Roma, people with a criminal conviction, people with life experience,&#8221; continued Massey.</p>
<p>The course is run by the university&#8217;s <a href="https://www.maynoothuniversity.ie/applied-social-studies">Department of Applied Social Studies</a>, it focuses on social justice and human rights, and there are currently around a dozen people on the course. The learning takes place on and off campus and the students have just returned from a study visit to the Inis Oírr.</p>
<figure aria-describedby="caption-attachment-252873"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2023/04/Maynooth-students-pictured-on-a-recent-study-trip-to-Inis-Oirr-3.png" alt="" width="1369" height="696" srcset="https://changingireland.ie/wp-content/uploads/2023/04/Maynooth-students-pictured-on-a-recent-study-trip-to-Inis-Oirr-3.png 1369w, https://changingireland.ie/wp-content/uploads/2023/04/Maynooth-students-pictured-on-a-recent-study-trip-to-Inis-Oirr-3-300x153.png 300w, https://changingireland.ie/wp-content/uploads/2023/04/Maynooth-students-pictured-on-a-recent-study-trip-to-Inis-Oirr-3-1024x521.png 1024w, https://changingireland.ie/wp-content/uploads/2023/04/Maynooth-students-pictured-on-a-recent-study-trip-to-Inis-Oirr-3-768x390.png 768w, https://changingireland.ie/wp-content/uploads/2023/04/Maynooth-students-pictured-on-a-recent-study-trip-to-Inis-Oirr-3-1080x549.png 1080w" sizes="(max-width: 1369px) 100vw, 1369px" /><figcaption><em>• Maynooth students pictured on a recent study trip to Inis Oírr.</em></figcaption></figure>
<p>Students normally do two placements during the two years.</p>
<p>&#8220;The work placements are really worth having on a CV coming out the other end,&#8221; said Massey. She encourages people to make contact as there may be other options that suit them, eg studying part-time over three years.</p>
<p>While mature student numbers are &#8220;down 10% across the board&#8221;, reflecting a national trend, Massey is optimistic and the number of graduate opportunities is growing.</p>
<p>&#8220;The Sector is changing and there&#8217;s a bit of a resurgence,&#8221; she said, pointing to the expanding <a href="https://www.cwi.ie/department-of-rural-and-community-development-launches-pilot-community-development-programme/">Community Development Pilot Programme</a> as just one example.</p>
<p>&nbsp;</p>
<figure aria-describedby="caption-attachment-252877"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2023/04/Former-and-current-students-at-a-recent-inclusion-and-migration-event-in-Maynooth-University.jpg" alt="" width="1577" height="1124" srcset="https://changingireland.ie/wp-content/uploads/2023/04/Former-and-current-students-at-a-recent-inclusion-and-migration-event-in-Maynooth-University.jpg 1577w, https://changingireland.ie/wp-content/uploads/2023/04/Former-and-current-students-at-a-recent-inclusion-and-migration-event-in-Maynooth-University-300x214.jpg 300w, https://changingireland.ie/wp-content/uploads/2023/04/Former-and-current-students-at-a-recent-inclusion-and-migration-event-in-Maynooth-University-1024x730.jpg 1024w, https://changingireland.ie/wp-content/uploads/2023/04/Former-and-current-students-at-a-recent-inclusion-and-migration-event-in-Maynooth-University-768x547.jpg 768w, https://changingireland.ie/wp-content/uploads/2023/04/Former-and-current-students-at-a-recent-inclusion-and-migration-event-in-Maynooth-University-1536x1095.jpg 1536w, https://changingireland.ie/wp-content/uploads/2023/04/Former-and-current-students-at-a-recent-inclusion-and-migration-event-in-Maynooth-University-400x284.jpg 400w, https://changingireland.ie/wp-content/uploads/2023/04/Former-and-current-students-at-a-recent-inclusion-and-migration-event-in-Maynooth-University-1080x770.jpg 1080w" sizes="(max-width: 1577px) 100vw, 1577px" /><figcaption><em>• Former and current students and staff at a recent inclusion and migration event in Maynooth University &#8211; Mairead McDevitt, Niamh Slevin, Holly Bardon, Linda Mackey, Richie Keane, Anastasia Crickley, Deirdre Massey, Marianne O&#8217;Shea, Ciara Shanahan, Rachel Doyle.</em></figcaption></figure>
<p>Graduates from this and related courses in Maynooth go on to forge careers as community workers, youth workers, climate and environmental justice workers, advocates for Traveller and Roma rights, migrant rights, LTBT+ work, anti-racism and intercultural work and policy work.</p>
<p>The online event takes place from 6.30-8pm and the Teams link for joining the session is: <a href="https://bit.ly/40WThu7">https://bit.ly/40WThu7</a></p>
<p>&nbsp;</p>
<h2>Some past pupils include:</h2>
<figure aria-describedby="caption-attachment-252876"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2023/04/Senator-Eileen-Flynn-graduated-from-Maynooth-University-in-2017-with-a-degree-in-Community-and-Youth-work.jpeg" alt="" width="1600" height="1066" srcset="https://changingireland.ie/wp-content/uploads/2023/04/Senator-Eileen-Flynn-graduated-from-Maynooth-University-in-2017-with-a-degree-in-Community-and-Youth-work.jpeg 1600w, https://changingireland.ie/wp-content/uploads/2023/04/Senator-Eileen-Flynn-graduated-from-Maynooth-University-in-2017-with-a-degree-in-Community-and-Youth-work-300x200.jpeg 300w, https://changingireland.ie/wp-content/uploads/2023/04/Senator-Eileen-Flynn-graduated-from-Maynooth-University-in-2017-with-a-degree-in-Community-and-Youth-work-1024x682.jpeg 1024w, https://changingireland.ie/wp-content/uploads/2023/04/Senator-Eileen-Flynn-graduated-from-Maynooth-University-in-2017-with-a-degree-in-Community-and-Youth-work-768x512.jpeg 768w, https://changingireland.ie/wp-content/uploads/2023/04/Senator-Eileen-Flynn-graduated-from-Maynooth-University-in-2017-with-a-degree-in-Community-and-Youth-work-1536x1023.jpeg 1536w, https://changingireland.ie/wp-content/uploads/2023/04/Senator-Eileen-Flynn-graduated-from-Maynooth-University-in-2017-with-a-degree-in-Community-and-Youth-work-1080x720.jpeg 1080w" sizes="(max-width: 1600px) 100vw, 1600px" /><figcaption><em>• Senator Eileen Flynn graduated from Maynooth University in 2017 with a degree in Community and Youth work.</em></figcaption></figure>
<figure aria-describedby="caption-attachment-252872"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2023/04/Maynooths-Dept-of-AppSocSc-graduate-1.jpeg" alt="" width="1280" height="720" srcset="https://changingireland.ie/wp-content/uploads/2023/04/Maynooths-Dept-of-AppSocSc-graduate-1.jpeg 1280w, https://changingireland.ie/wp-content/uploads/2023/04/Maynooths-Dept-of-AppSocSc-graduate-1-300x169.jpeg 300w, https://changingireland.ie/wp-content/uploads/2023/04/Maynooths-Dept-of-AppSocSc-graduate-1-1024x576.jpeg 1024w, https://changingireland.ie/wp-content/uploads/2023/04/Maynooths-Dept-of-AppSocSc-graduate-1-768x432.jpeg 768w, https://changingireland.ie/wp-content/uploads/2023/04/Maynooths-Dept-of-AppSocSc-graduate-1-1080x608.jpeg 1080w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption><em>• Amy Michelle Collins graduated in 2019 with a degree in Community and Youth work.</em></figcaption></figure>
<figure aria-describedby="caption-attachment-252878"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2023/04/Maynooths-Dept-of-AppSocSc-graduate-2.jpeg" alt="" width="1280" height="720" srcset="https://changingireland.ie/wp-content/uploads/2023/04/Maynooths-Dept-of-AppSocSc-graduate-2.jpeg 1280w, https://changingireland.ie/wp-content/uploads/2023/04/Maynooths-Dept-of-AppSocSc-graduate-2-300x169.jpeg 300w, https://changingireland.ie/wp-content/uploads/2023/04/Maynooths-Dept-of-AppSocSc-graduate-2-1024x576.jpeg 1024w, https://changingireland.ie/wp-content/uploads/2023/04/Maynooths-Dept-of-AppSocSc-graduate-2-768x432.jpeg 768w, https://changingireland.ie/wp-content/uploads/2023/04/Maynooths-Dept-of-AppSocSc-graduate-2-1080x608.jpeg 1080w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption><em>• Debbie O&#8217;Rourke graduated in 2014 with a degree in Community and Youth work.</em></figcaption></figure>', 'Readers wondering should they study for a masters in youth and community work at Maynooth University can hear what it’s like this coming Monday, April 24th, when current students take part in a questions and answers session.', 'https://changingireland.ie/wp-content/uploads/2023/04/Maynooth-students-pictured-on-a-recent-study-trip-to-Inis-Oirr.png', '', '[{"slug":"education-training","title":"Education & Training"}]', '[{"slug":"community-development","title":"community development"},{"slug":"maynooth-university","title":"Maynooth University"},{"slug":"youth-work","title":"youth work"}]', '', 252870, 1, '2023-04-21T13:46:13Z', '2023-04-21T15:47:54Z', '2023-04-21T13:46:13Z')
