INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('New report highlights services for people with neurological conditions', 'new-report-highlights-services-for-people-with-neurological-conditions', '<p>It also shows that there are over 60 community-based voluntary organisations supporting those people, providing a wide variety of services in response to their needs.</p>
<p>The report highlights that the vast majority of the 800,000 people living with neurological conditions across Ireland, live within the community.</p>
<p>The report was a joint partnership between the Health Service Executive (HSE), the Disability Federation of Ireland (DFI) and the Neurological Alliance of Ireland (NAI), funded by the Strengthening Disability Fund.</p>
<p>The three key outputs from the Neuro-Mapping project are:</p>
<ul>
<li>The development of a unique service mapping template which identifies services across Ireland, categorising them together with agreed and standardised service descriptors.</li>
<li>Baseline Mapping of all services across each Community Healthcare Organisation (CHO), showing the range and scale of neuro-rehabilitation supports provided in the community by voluntary organisations.</li>
<li>Documented good practice examples of joint service initiatives between voluntary sector providers and statutory services provided by the HSE.</li>
</ul>
<p>The Project Partners (DFI, HSE and NAI) have agreed to progress several key actions in the next phase of the project to address the report’s findings.</p>
<p>The service mapping template will need to be developed to encompass statutory service provision and establish a common language for all neurological community service provision. It will also be important to assimilate the language used in the mapping template into future service frameworks.</p>
<p>Engagement with both statutory and voluntary providers is required to understand how neurorehabilitation services are delivered on the ground in communities and how voluntary organisations work with each other and HSE services. This will help to provide insight into the variations in the services, and patient pathways across CHOs, as well as the impact of community neurorehabilitation teams where these are in place.</p>
<p>It is also intended to examine the current journey through these services, through the experiences of people with neurological conditions and their families, and this will demonstrate ways to improve signposting to existing supports.</p>
<p>The report is available to read in full <a href="https://www.disability-federation.ie/assets/files/pdf/neuro_mapping_project_report_19_april_2023.pdf">here</a></p>', 'A new report putting a spotlight on the community services available nationwide for people with neurological conditions was launched yesterday by Minister for Disability Anne Rabbitte. The Neuro-Mapping Project Report describes the range of community services across the country that people with neurological conditions can access from voluntary organisations, and identifies a number of joint service initiatives between voluntary organisations and the HSE.', 'https://changingireland.ie/wp-content/uploads/2023/04/DFI-mapping-project2.jpeg', '', '[{"slug":"empowerment","title":"Empowerment"}]', '[{"slug":"community-development","title":"community development"},{"slug":"community-healthcare-organisation-cho","title":"Community Healthcare Organisation (CHO)"},{"slug":"disability-federation-of-ireland-dfi","title":"Disability Federation of Ireland (DFI)"},{"slug":"healthcare","title":"healthcare"},{"slug":"hse-health-service-executive","title":"HSE"},{"slug":"ireland","title":"Ireland"},{"slug":"minister-anne-rabbitte","title":"Minister Anne Rabbitte"},{"slug":"minister-for-disability-anne-rabbitte","title":"Minister for Disability Anne Rabbitte"},{"slug":"neurological-alliance-of-ireland-nai","title":"Neurological Alliance of Ireland (NAI)"},{"slug":"neurological-conditions","title":"neurological conditions"},{"slug":"strengthening-disability-fund","title":"Strengthening Disability Fund"}]', '', 252865, 1, '2023-04-20T13:27:34Z', '2023-04-20T13:27:34Z', '2023-04-20T13:27:34Z')
