INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('2023 calendar of capital investment schemes published', '2023-calendar-of-capital-investment-schemes-published', '<p>Encouraging community groups to apply, Minister Heather Humphreys said: “There has never been as many opportunities for local community groups to access funding for rural and community development projects. I am anxious to make this funding as accessible as possible, and with this in mind I am now publishing the details of when the main capital investment schemes will be open for applications in 2023.</p>
<p>“This will help community groups and local authorities to see what funding is available, and when, and will assist them in the planning of their applications”.</p>
<p>The 2023 schemes include: the Town and Village Renewal Scheme, the Community Centre Investment Fund, the CLÁR Programme, and the Outdoor Recreation Infrastructure Scheme</p>
<p>The full DRCD calendar of 2023 schemes is available at https://www.gov.ie/en/publication/0bb45-drcd-calendar-of-schemes-2023/</p>
<p>&nbsp;</p>', 'The Department of Rural and Community Development has announced details of when the main capital investment schemes will be opening in 2023.', 'https://changingireland.ie/wp-content/uploads/2019/08/money-1005477_1280.jpg', '50 euro notes', '[{"slug":"funding","title":"Funding"}]', '[{"slug":"capital-investment-schemes","title":"capital investment schemes"},{"slug":"clar-programme","title":"CLÁR Programme"},{"slug":"community-centre-investment-fund","title":"Community Centre Investment Fund"},{"slug":"community-development","title":"community development"},{"slug":"community-groups","title":"community groups"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"funding","title":"funding"},{"slug":"local-authorities","title":"local authorities"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"outdoor-recreation-infrastructure-scheme","title":"Outdoor Recreation Infrastructure Scheme"},{"slug":"town-and-village-renewal-scheme","title":"Town and Village Renewal Scheme"}]', '', 252831, 1, '2023-03-28T11:42:13Z', '2023-03-27T11:46:18Z', '2023-03-28T11:42:13Z')
