INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('New initiative to transform vacant buildings into community facilities', 'new-initiative-to-transform-vacant-buildings-into-community-facilities', '<p>Every local authority in the country can apply for funding of up to €500,000, which they can use to purchase up to three properties to redevelop.</p>
<p>Funding previously announced under the scheme saw former banks, courthouses, Garda stations and FCA halls all purchased and repurposed for 21st century use.</p>
<figure aria-describedby="caption-attachment-252837"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2023/03/Presentation-Convent-Bagenalstown-Co-Carlow-300x226.png" alt="" width="300" height="226" srcset="https://changingireland.ie/wp-content/uploads/2023/03/Presentation-Convent-Bagenalstown-Co-Carlow-300x226.png 300w, https://changingireland.ie/wp-content/uploads/2023/03/Presentation-Convent-Bagenalstown-Co-Carlow.png 582w" sizes="(max-width: 300px) 100vw, 300px" /><figcaption><em>Presentation Convent, Bagenalstown, Co Carlow, one of the buildings acquired under last year&#8217;s initiative</em></figcaption></figure>
<p>Minister for Rural and Community Development, Heather Humphreys, said:</p>
<p>“This is all about building on the momentum that ‘Our Rural Future’ has delivered. It’s a huge opportunity for us all to work together in tackling the scourge of dereliction and transforming old run-down buildings into facilities that will benefit communities for generations to come.”</p>
<p>Since the launch of the Town and Village Renewal Scheme, over €149 million has been allocated to more than 1,600 projects.</p>
<p>Applications under the Building Acquisition Measure must be submitted by April 28; further details can be found <a href="https://www.gov.ie/en/policy-information/01125e-town-and-village-renewal-scheme/#2023-building-acquisition-measure">here.</a></p>
<figure aria-describedby="caption-attachment-252839"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2023/03/Former-Bank-of-Ireland-Building-Lismore-Co-Waterford-300x225.png" alt="" width="300" height="225" srcset="https://changingireland.ie/wp-content/uploads/2023/03/Former-Bank-of-Ireland-Building-Lismore-Co-Waterford-300x225.png 300w, https://changingireland.ie/wp-content/uploads/2023/03/Former-Bank-of-Ireland-Building-Lismore-Co-Waterford.png 555w" sizes="(max-width: 300px) 100vw, 300px" /><figcaption>Former Bank of Ireland Building, Lismore, Co Waterford</figcaption></figure>', 'A new €13 million fund launched today (Monday, March 27) aims to tackle vacancy and dereliction in rural Ireland. The funding, under the Town and Village Renewal Scheme, will see dozens of old, unused buildings transformed into multi-purpose community facilities.', 'https://changingireland.ie/wp-content/uploads/2023/03/Parochial-House-Feohanagh-Co-Limerick.jpg', '', '[{"slug":"funding","title":"Funding"}]', '[{"slug":"building-acquisition-measure","title":"Building Acquisition Measure"},{"slug":"community","title":"Community"},{"slug":"community-facilities","title":"community facilities"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"dereliction","title":"dereliction"},{"slug":"funding","title":"funding"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"our-rural-future","title":"Our Rural Future"},{"slug":"town-and-village-renewal-scheme","title":"Town and Village Renewal Scheme"},{"slug":"vacant-buildings","title":"vacant buildings"}]', '', 252828, 1, '2023-03-27T11:01:14Z', '2023-03-27T14:26:21Z', '2023-03-27T11:01:14Z')
