INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Funding announced to help community and voluntary groups pay energy bills', 'funding-announced-to-help-community-and-voluntary-groups-pay-energy-bills', '<div role="main">
<div>
<div>
<div>
<div></div>
</div>
</div>
</div>
</div>
<div>
<div>
<div>
<div>
<div>
<div>
<div>
<p>Hundreds of groups have already benefitted under the scheme, which was launched last year in response to the rising cost of energy and the impact it is having on the sector.</p>
</div>
</div>
<div>
<div>
<p>Now, a further 134 groups are to receive grants as part of an overall investment of almost €189,000. Payments will issue to the organisations immediately.</p>
</div>
</div>
<div>
<div>
<p>The funding brings the total number of organisations supported under the initiative to 552, with over €705,000 now disbursed.</p>
</div>
</div>
<div>
<div>
<p>Among the successful applicants include:</p>
</div>
</div>
<div>
<div>
<ul>
<li>Clare – Kilrush Amenity Trust: €4,160</li>
<li>Dublin &#8211; Finglas Youth Resource Centre: €2,497</li>
<li>Cork – Comhaltas Cosanta Gaeltachta Chuil Aodha Teoranta: €2,918</li>
<li>Roscommon – Enterprise Castlerea: €3,989</li>
<li>Galway – Galway Rape Crisis Centre: €2,731</li>
</ul>
</div>
</div>
<div>
<div>
<p>Announcing the funding during a recent visit to Enterprise Castlerea in Roscommon, Minister Humphreys said:</p>
</div>
</div>
<div>
<div>
<blockquote><p>“Although the winter months are behind us, energy bills remain high and this is posing particular challenges for our community and voluntary sector. The grants being announced today may be small in nature, but they will give a bit of breathing space for groups that deliver essential services, supports and facilities to communities all over Ireland. Today’s investment means that over 550 groups have now been helped under this scheme, which remains open for applications until 24 March. I am also pleased to extend the Scheme to Section 39 organisations. Our communities depend on these organisations, and it is only right that we do what we can to support them.”</p></blockquote>
</div>
</div>
<div>
<div>
<p>Minister O Brien added:</p>
</div>
</div>
<div>
<div>
<blockquote><p>“I hope the funding announced today, together with the expansion of the scheme will go some way to addressing the current pressures brought by increased energy costs and enable the organisations to get on with providing vital services and supports. The inclusion of section 39 organisations will ensure that these organisations are treated on an equal basis as all other organisations in the sector. Further tranches of funding will follow shortly. We are also keeping the application process open until 24 March to give all eligible groups in the voluntary and community sector the opportunity to apply for support.”</p></blockquote>
</div>
</div>
<div>
<div>
<h2>Expansion to include Section 39 organisations</h2>
</div>
</div>
<div>
<div>
<p>The Ministers also confirmed that the scheme will remain open until March 24 and will be expanded to include organisations in receipt of Section 39 funding from the HSE.</p>
</div>
</div>
<div>
<div>
<p>This is to ensure that community and voluntary organisations and charities that are part funded by the HSE under Section 39, receive the same levels of support towards energy costs as non-Section 39 organisations.</p>
</div>
</div>
<div>
<div>
<p>Such organisations will be able to seek additional funding to meet any shortfall in the top-up funding they receive from the HSE or Department of Health, up to the level that is approved for other community and voluntary organisations, under the CVESS.</p>
</div>
</div>
<div>
<div>
<p>The Ministers also confirmed that the scheme is now open to incorporated community and voluntary organisations or charities who have been refused support under the Temporary Business Energy Support Scheme (TBESS), on the grounds that they are engaged in passive trade. Such organisations should apply in the normal way, providing confirmation from the Revenue Commissioners that they are ineligible under TBESS.</p>
</div>
</div>
<div>
<div>
<p>All the information is on the Pobal website and a dedicated helpdesk can be reached at <a href="mailto:energyscheme@pobal.ie">energyscheme@pobal.ie</a></p>
</div>
</div>
<div>
<div>
<p>The government is urging householders and businesses to ensure that they are availing of the supports that are in place. For more information visit <a href="https://www.gov.ie/en/campaigns/6ca43-reduce-your-use/">gov.ie/reduceyouruse.</a></p>
</div>
</div>
<div>
<div>
<p><a href="https://www.gov.ie/en/collection/08468-community-voluntary-energy-support-scheme-cvess/">Click here for full list of successful applicants.</a></p>
</div>
</div>
</div>
</div>
</div>
</div>
</div>', 'A funding scheme to support 134 community and voluntary groups with their energy bills was announced this week. Under the Community and Voluntary Energy Support Scheme (CVESS), small grants are provided to community groups, development associations, and volunteer-led organisations.', 'https://changingireland.ie/wp-content/uploads/2023/03/CCVESS.jpg', '', '[{"slug":"funding","title":"Funding"}]', '[{"slug":"community-and-voluntary-energy-support-scheme-cvess","title":"Community and Voluntary Energy Support Scheme (CVESS)"},{"slug":"community-and-voluntary-organisations","title":"community and voluntary organisations"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"hse-health-service-executive","title":"HSE"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"minister-joe-obrien","title":"Minister Joe O''Brien"},{"slug":"pobal","title":"Pobal"},{"slug":"section-39","title":"Section 39"},{"slug":"temporary-business-energy-support-scheme-tbess","title":"Temporary Business Energy Support Scheme (TBESS)"}]', '', 252760, 1, '2023-03-01T12:56:51Z', '2023-03-01T12:56:51Z', '2023-03-01T12:56:51Z')
