INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Comrade Dermot Hayes to publish his memoirs', 'comrade-dermot-hayes-to-publish-his-memoirs', '<p>He calls all his friends ‘Comrade’ and has been active for decades in youth work, community groups, LEADER projects, trade unions, worker co-ops, environmental causes, and disability rights.</p>
<p>Dermot lives in Ennis, Co. Clare, and is known for volunteering, advocating and campaigning for human rights, in particular with the Independent Living Movement in Ireland.</p>
<p>He spent the last year writing his memoirs with the aid of well-known ghostwriter Breda Shannon.</p>
<p>“I have been immersed in the local, national and international movement for over thirty years. During this time, I founded, co-founded and headed organisations to represent, campaign and progress rights for people with disabilities,&#8221; he says.</p>
<p>“The book explores and documents my life as a child growing up in Kells, Corofin, County Clare and through to my years as an activist and campaigner across many causes over seven decades,&#8221; says Dermot.</p>
<p>The book will be launched at 6pm, on March 4, by Andrea Barry and Patrick McCormack in St. Patrick&#8217;s Hall, Corofin, Co. Clare.</p>
<p>All profits from &#8216;The Road that Rises&#8217; will be donated to two causes: the Clare Leader Forum and the Corofin Hall and Field Fund. You can buy the book in Clare shops. If living outside Co. Clare, contact Dermot on Twitter: @HayesEnnis</p>', 'Nationally known disability activist and community campaigner Comrade Dermot Hayes is about to publish his memoirs under the title ‘The Road That Rises – a memoir by Dermot Hayes, a boy from Kells’. Like many activists and volunteers, Dermot is a force of nature.', 'https://changingireland.ie/wp-content/uploads/2023/02/Dermot-Hayes-is-pubg-his-memoir-launch-on-March-4th-Sat-2.jpg', '', '[{"slug":"activism-volunteering","title":"Activism & Volunteering"}]', '[{"slug":"activism","title":"activism"},{"slug":"andrea-barry","title":"Andrea Barry"},{"slug":"clare","title":"Clare"},{"slug":"clare-leader-forum","title":"Clare Leader Forum"},{"slug":"clare-local-development-company","title":"Clare Local Development Company"},{"slug":"clare-public-participation-network-ppn","title":"Clare Public Participation Network (PPN)"},{"slug":"community-development","title":"community development"},{"slug":"comrade-dermot-hayes","title":"Comrade Dermot Hayes"},{"slug":"corofin","title":"Corofin"},{"slug":"disability-activism","title":"Disability Activism"},{"slug":"independent-living-movement-ireland","title":"Independent Living Movement Ireland"},{"slug":"memoir","title":"Memoir"},{"slug":"patrick-mccormack","title":"Patrick McCormack"},{"slug":"west-clare","title":"West Clare"}]', '', 252713, 1, '2023-02-23T20:39:03Z', '2023-02-24T12:55:27Z', '2023-02-23T20:39:03Z')
