INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Shamrock Squad working to make the outdoors accessible to all', 'shamrock-squad-working-to-make-the-outdoors-accessible-to-all', '<p><span>The social enterprise is a community of special needs families who work with support agencies, service providers and other special needs families to make the outdoors accessible for all needs.</span></p>
<p><span>Vika Gailite, Shamrock Squad Adventures co-founder told Changing Ireland: “We are trying to make the outdoors as inclusive as possible. Most of our children are on the (autism) spectrum. Some have physical disabilities or other intellectual disabilities. We organise walks, nature walks and litter-picking.</span></p>
<p><span>“You look on websites and there is information about wheelchair accessibility, but other special needs families are neglected. There are people with hidden disabilities that you can’t see. You could go out and the child could have a meltdown, sensory overload, and you don’t know what’s there that could trigger them.”</span></p>
<p><span>The network includes ten dedicated families who conduct ‘review walks’, to investigate if a route is suitable for those with additional needs. </span></p>
<p><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2023/02/shamsquad-300x225.jpg" alt="" width="300" height="225" srcset="https://changingireland.ie/wp-content/uploads/2023/02/shamsquad-300x225.jpg 300w, https://changingireland.ie/wp-content/uploads/2023/02/shamsquad-1024x768.jpg 1024w, https://changingireland.ie/wp-content/uploads/2023/02/shamsquad-768x576.jpg 768w, https://changingireland.ie/wp-content/uploads/2023/02/shamsquad-1536x1152.jpg 1536w, https://changingireland.ie/wp-content/uploads/2023/02/shamsquad-1080x810.jpg 1080w, https://changingireland.ie/wp-content/uploads/2023/02/shamsquad.jpg 2048w" sizes="(max-width: 300px) 100vw, 300px" /></p>
<p><span>Shamrock Squad Adventures also organises ‘open walks’ that are attended by between 15 and 20 families.</span></p>
<p><span>Vika explained: “We try to make it as easy as possible for them to do these walks. It can be crazy hard to go outdoors when you have someone in your family with special needs. You want to make it as fun as possible for everyone, but most of the time you end up having to turn back and the family can’t enjoy the outing.”</span></p>
<p><span>Shamrock Squad Adventures aims to reach local authorities around the country to advise them which of the walks in their areas are suitable for people with special needs, and what improvements could be made.</span></p>
<p><span>‘United Women’ from Action Tuam is a group of refugee and migrant women living in direct provision in Galway who were ‘Highly Commended’ by the judges at the National Pitch-Fest.</span></p>
<p><span>The women have come together to support each other and their community. Their ambition is to form a social enterprise using food to integrate communities, promote cultural identity, teach life skills, educate others on their traditions and create employment. </span></p>
<p><span>Other ideas presented to the judges featured a new eco concrete solution, a digital support platform for new parents from minority groups, social integration through music and an online marketplace connecting lift-seekers with vehicle owners.</span></p>
<p><span>The prize bursary awarded to Shamrock Squad Adventures includes: five dedicated mentoring sessions facilitated by the Local Enterprise Network, access to ReThink Ireland’s ‘Start your own Social Enterprise Programme’, legal advice from Arthur Cox, and a hot desk space for six months.</span></p>
<p><span>Shamrock Squad Adventures said they hope to use the bursary “to accelerate the platform development”.</span></p>
<p><span>Vika added: “We are so delighted. It’s the recognition; that what you’re doing is needed and is worthwhile. The mentorship is gold &#8211; to have access to these people and to be able to pick their brains.”</span></p>
<p><span>She revealed that their longterm goals include the development of a centre of excellence, to help families learn to navigate the outdoors with their children who have special needs.</span></p>
<p><span>“The sky’s the limit!” she concluded. </span></p>
<p><span>Siobhán Finn, National Hub Network Manager at CEAI (Community Enterprise Association Ireland) said: “The energy, enthusiasm and creativity we saw from the finalists at the National Pitch-Fest was amazing. It was clear every participant is passionate about tackling social and environmental issues and creating positive change in their communities. </span></p>
<p><span>“We are so grateful to our excellent judges that were involved in the National Pitch-Fest, all the enterprise centres and hubs who participated in hosting the regional events and our brilliant partners who provided the range of supports and services included in the Prize Bursary. It was a privilege to witness such a high standard of social enterprise ideas and pitches, particularly during a time where these solutions are critical in society and to the economy.”</span></p>
<p><span>She remarked that Shamrock Squad Adventures’ pitch was “incredible”.</span></p>
<p><span>“They deserve all the success going forward. I cannot wait to follow their social enterprise journey and watch it become a reality,” Ms Finn concluded.</span></p>
<p><span>Pauline Gannon, co-founder and Director of Impact, Social Impact Ireland on behalf of the judging panel said: </span><span>“Champion Changemakers has provided a platform that supports community changemakers to develop solutions to the challenges they experience within their own communities, giving national recognition and supports, to local innovation.”</span></p>
<p><span>She added that the projects “offer real solutions to overcome real challenges within communities across Ireland”.</span></p>
<p><span> </span></p>', 'An initiative founded by two women hoping to open up more outdoor spaces to children with additional needs was named the winner of the Champion Changemakers National Pitch-Fest in late 2022. Shamrock Squad Adventures, from RDI Hub and Dingle Hub in Kerry, received a prize bursary of supports and services valued at €10,000 to further develop their project.', 'https://changingireland.ie/wp-content/uploads/2023/02/shamsquad2.jpg', '', '[{"slug":"community","title":"Community"}]', '[{"slug":"arthur-cox","title":"Arthur Cox"},{"slug":"champion-changemakers","title":"Champion Changemakers"},{"slug":"community-enterprise-association-ireland","title":"Community Enterprise Association Ireland"},{"slug":"dingle-hub","title":"Dingle Hub"},{"slug":"local-enterprise-network","title":"Local Enterprise Network"},{"slug":"rdi-hub","title":"RDI Hub"},{"slug":"rethink-ireland","title":"ReThink Ireland"},{"slug":"shamrock-squad-adventures","title":"Shamrock Squad Adventures"},{"slug":"social-impact-ireland","title":"Social Impact Ireland"},{"slug":"special-needs","title":"special needs"}]', '', 252659, 1, '2023-02-08T10:44:52Z', '2023-02-08T10:45:25Z', '2023-02-08T10:44:52Z')
