INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Government funders must treat civil society groups with more respect', 'govt-funders-must-treat-civil-society-groups-with-more-respect', '<p>Developed by the sector, in partnership with Government, the aim is to support values such as social justice, and active participation along with principles like respect, collaboration and value for money.</p>
<p>From now on five values and six principles apply when local and national government is working with community groups.</p>
<p>It’s not law, so local authorities, agencies and government departments are not obliged to follow it, but the push is on for them to start signing up.</p>
<p>Remarking on the need for such a drive, Ivan Cooper pointed out that one in three people delivering public services in Ireland today work for a charity, a community group or a social enterprise. The sector, he reminded everyone, has an annual turnover of over €14 billion and employs 165,000 people. He described this as “startling” and was of the view that these figures still had not sunk in among those devising policy.</p>
<p>The agreed values are:<br />
1. Social Justice.<br />
2. Empowering Communities, Sustainable Development.<br />
3. Active Participation.<br />
4. Human Rights, Equality and Anti-Discrimination.<br />
5. Social Inclusion.</p>
<p>The agreed principles are:<br />
1. Respect.<br />
2. Subsidiarity.<br />
3. Harmonisation.<br />
4. Value for Money.<br />
5. Implementation.<br />
6. Collaboration.</p>
<p>The launch took place in Outhouse Resource Centre in Capel Street, Dublin, an organisation supporting the LGBT+ community, their friends, families and allies.</p>
<p>The values and principles document relates to plans first outlined in an earlier policy document launched by the Government in 2019 called ‘Sustainable, Inclusive and Empowered Communities’.</p>
<p>Videos of the speeches by Mr Cooper, Ms Doyle and Minister O’Brien can be viewed on <a href="https://www.youtube.com/watch?v=VUN3mBek1f0&amp;list=PLLqAt9ZHNb4g2DDGpnyX_XaFgHqcLlr1Y">‘Changing Ireland’s Youtube channel.</a></p>', 'An overdue document was launched by Minister of State for Community Development, Joe O’Brien, with help from Ivan Cooper of The Wheel and Rachel Doyle of Community Work Ireland, on October 19. It was overdue in so much as it could be helpful for a couple living together for years, even if they sometimes drive each other bananas, to see what they actually agree on. The seven-page document outlines an agreed set of values and principles to be used by central and local government, as well as state…', 'https://changingireland.ie/wp-content/uploads/2023/01/IMG_5448-scaled-e1674855314665.jpeg', '', '[{"slug":"empowerment","title":"Empowerment"},{"slug":"equality-rights","title":"Equality & Rights"}]', '[{"slug":"community","title":"Community"},{"slug":"community-development","title":"community development"},{"slug":"community-work","title":"community work"},{"slug":"community-work-ireland","title":"Community Work Ireland"},{"slug":"ivan-cooper","title":"Ivan Cooper"},{"slug":"minister-joe-obrien","title":"Minister Joe O''Brien"},{"slug":"outhouse-resource-centre","title":"Outhouse Resource Centre"},{"slug":"public-service","title":"public service"},{"slug":"rachel-doyle","title":"Rachel Doyle"},{"slug":"the-wheel","title":"The Wheel"},{"slug":"values-and-principles","title":"values and principles"}]', '', 252523, 1, '2023-01-27T21:04:36Z', '2023-02-07T11:02:41Z', '2023-01-27T21:04:36Z')
