INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Minister stresses State and sector both want empowered communities', 'minister-stresses-state-and-sector-both-want-empowered-communities', '<p>“These will form the bedrock of engagement and collaboration going forward. I am very proud of our record in working with the community and voluntary sector, but I know we can always go further. Our mutual objective is to support and empower communities and the individuals within those communities.”</p>
<p>He said both sides had “come to a shared understanding&#8221; and he hailed &#8220;the values and principles that bind and drive both the sector and state.”</p>
<p>“These values and principles will support consultation, inclusion and participation of communities, particularly disadvantaged communities, in public policy and decision-making at all levels and forms a foundation for collective approaches to local and national issues,” he said.</p>
<p>“The success of this initiative will ultimately be in the realisation and embedding of these Values and Principles, and I look forward to championing them,&#8221; he added.</p>
<p>He said he had checked with his Department and the values and principles have been “warmly welcomed” by other government departments. It was important to spread the word widely, he said.</p>
<p>“A lot of people in the community and voluntary sector don’t know that the government has bought into this.</p>
<p>“My Department will champion these values and principles as well as ensuring they remain at the heart of all we do,” he said.</p>
<p>He singled out one value and one principle and quoted both in full from the document. These are the value of active participation and the principle of subsidiarity.</p>
<p>From now on, the document is intended to be widely used in interactions with the community and voluntary sector.</p>
<p>The seven-page document is available online at: <a href="https://www.gov.ie/en/publication/d4445-values-and-principles-for-collaboration-and-partnership-working/">https://www.gov.ie/en/publication/d4445-values-and-principles-for-collaboration-and-partnership-working/</a></p>', 'Officially launching the values and principles document, Minister of State at the Department of Rural and Community Development, Joe O’Brien, said: “The publication of these values and principles copper-fastens the renewed relationship and partnership between government and the community and voluntary sector, which has been central in addressing the crises of recent times.”', 'https://changingireland.ie/wp-content/uploads/2023/01/IMG_0703-scaled.jpg', '', '[{"slug":"development-work","title":"Development Work"}]', '[]', '', 252527, 1, '2023-01-27T21:03:24Z', '2023-01-31T17:58:09Z', '2023-01-27T21:03:24Z')
