INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Department aware of recruitment issues in C&V sector', 'department-aware-of-difficulties-recruiting-and-retaining-staff', '<p>Changing Ireland sought comment after speaking to people working in the sector who reported difficulties around the recruitment and retention of employees in the sector, which is having an impact on their services and relationships. The main issue they are reporting is the loss of staff to State organisations such as the HSE, as they cannot compete with the salaries on offer.</p>
<p>We also asked if the Department had any information on any future plans to increase funding to Section 10, 56, and 39 organisations to help raise salaries in the sector.</p>
<p>In response, the Department issued the following statement:</p>
<blockquote><p>“DRCD are aware of the challenges facing organisations in the Local Development and Community Development Sectors around the recruitment and retention of staff. However, DRCD has no funding role in respect of Section 10, 56 and 39 organisations.”</p></blockquote>', 'The Department of Rural and Community Development issued a brief statement in response to a query from this publication on the issue of recruitment and retention in the community sector.', 'https://changingireland.ie/wp-content/uploads/2023/01/DRCD-logo-transparent-e1674855364907.png', '', '[{"slug":"income-employment","title":"Income & Employment"}]', '[{"slug":"community-and-voluntary-sector","title":"Community and Voluntary sector"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"pay","title":"pay"},{"slug":"recruitment","title":"recruitment"}]', '', 252521, 1, '2023-01-27T21:02:42Z', '2023-02-01T12:47:34Z', '2023-01-27T21:02:42Z')
